program RepeatUntilLoop;
var
   i: integer;

begin
   i := 1;

   repeat
      writeln('Gia tri i = ', i);
      i := i + 1;
   until i > 5;
end.

program NestedLoop;
var
   i, j: integer;

begin
   for i := 1 to 3 do
   begin
      for j := 1 to 2 do
      begin
         writeln('i = ', i, ', j = ', j);
      end;
   end;
end.

